with open('/Users/alex/lebotworld-office-game/stories.js', 'r', encoding='utf-8') as f:
    content = f.read()

extras = {}

extras['Alex'] = "\n\n【附录：Alex的一封家书】\n\n2024年春节，Alex回到了老家。父亲已经退休了，头发花白但精神矍铄。母亲的腰不太好，不能再长时间站着上课了。\n\n除夕夜，一家人围坐在饭桌前。Alex看着桌上丰盛的年夜饭，突然有些哽咽。他想起了小时候，年夜饭最好的菜就是外婆红烧的一盘排骨。现在他在大城市里当CEO，却越来越想念那个味道。\n\n饭后，他帮母亲收拾碗筷时，母亲轻声说：儿子，妈看到你上电视了。你做的那个机器人，真的能帮到孩子们吗？\n\n能的，妈。我们已经帮助了十万多个孩子了。\n\n那就好。母亲的眼眶有些湿润，你从小就喜欢捣鼓那些东西。妈一直相信你能做出点名堂来。\n\nAlex晚上睡不着，拿出手机，在备忘录里写下了一封不会发出的家书：\n\n亲爱的爸爸妈妈：谢谢你们。谢谢爸爸在我小的时候，每天下班后陪我玩那个只有几个零件的电子积木。谢谢妈妈省吃俭用，从牙缝里挤出钱来给我买了那台旧电脑。谢谢你们从来没有说过你不行或者别做梦了，而是默默地支持着我走的每一步。\n\n斓舟科技现在有八十多个员工了。每次新员工入职，我都会讲一个故事，一个关于泥人小镇的故事。那个故事的主角是六岁的我，和蹲在旁边看着我的外婆。\n\n外婆不在了。但她教会我的东西，我一辈子都不会忘，用双手创造温暖，用真心对待每一个人。\n\n我会继续做下去的。不是为了钱，不是为了名，而是为了那些像小时候的我一样的孩子。他们需要的不是多么昂贵的玩具，而是一个真心的伙伴。\n\n谢谢你们给了我一个温暖的家。我会把这份温暖，传递给更多的孩子。\n\n爱你们的儿子，Alex。\n\n他写完这封信后，静静地看了很久，然后锁上了手机。\n\n窗外，烟花在夜空中绽放。远处传来鞭炮声和孩子们的笑声。\n\n新的一年开始了。斓舟科技的旅程还在继续。而他知道，无论走多远，回家的路永远在那里。"

extras['鸽子'] = "\n\n【附录：一封来自麦田的信】\n\n2024年秋天，鸽子回老家参加堂弟的婚礼。\n\n婚礼在村里的祠堂举行，热闹非凡。鸽子穿着一件素雅的裙子，在人群中显得有些格格不入。不是因为她不属于这里，而是因为她走得太远，已经跟儿时的伙伴们有了太多不同的经历。\n\n婚礼结束后，她一个人走到了村口的大榕树下。那棵树比她记忆中的更大了，枝叶繁茂得像一把巨大的绿伞。\n\n她坐在树根上，靠着粗糙的树皮，闭上眼睛。风吹过来，带着远处麦田的气息。成熟的麦子、湿润的泥土、还有一丝说不清的乡愁。\n\n她想起了很多事。想起五岁时在这里给小伙伴们讲故事，想起父亲在木工坊里一边刨木头一边说做东西得想着用的人，想起母亲在煤油灯下读教育学书籍的背影。\n\n她也想起了在大厂的日子。每天被数据和KPI裹挟着奔跑，跑得很快但不知道方向在哪里。然后她遇到了Alex，遇到了斓舟科技，终于找到了方向。\n\n现在，她的故事已经通过斓舟科技的产品，传递给了几十万个孩子。有些孩子因为这些故事变得更加自信，有些孩子因为这些故事学会了表达，有些孩子因为这些故事找到了自己的第一个朋友。\n\n这就是我想做的事情。她自言自语。\n\n身后传来脚步声。她回头一看，是父亲。\n\n父亲也老了。头发全白了，背有些驼，但那双手依然粗糙有力。那是做了一辈子木工的手。\n\n丫头，坐这儿干啥呢？父亲在她旁边坐下。\n\n在想事情。\n\n想啥？\n\n鸽子沉默了一会儿，然后说：爸，我做的那些产品，真的有用吗？我真的在帮到那些孩子吗？\n\n父亲想了想，伸出那双布满老茧的手，指了指远处的麦田：你看那片麦子。我年轻的时候，那片地还是荒地。你爷爷带着我一锄头一锄头地开垦，年复一年地播种、浇水、施肥。刚开始几年收成不好，我们都怀疑过是不是选错了地方。但你爷爷说了一句话，我记到现在。\n\n什么话？\n\n地不会辜负汗水。只要种子是对的，迟早会有好收成。\n\n父亲看着她：你做的事情，种子是对的。别急，慢慢来。\n\n鸽子的眼眶湿润了。她把头靠在父亲的肩膀上，就像小时候一样。\n\n风吹过麦田，发出沙沙的声响，像是一首温柔的摇篮曲。\n\n她知道，无论飞得多远，这片麦田永远是她的起点，也是她的归处。"

extras['Evan'] = "\n\n【附录：Evan的健身房哲学课】\n\nEvan在斓舟科技的三年里，影响了很多同事的生活方式。他不是那种强推健身的人，但他的坚持本身就很有感染力。\n\n有一次，一个新入职的年轻工程师小张在项目遇到瓶颈时非常沮丧。Evan拉着他去了楼下的健身房。\n\n我不太会健身。小张有些不好意思。\n\n没关系，今天我们就做一件事，平板支撑。Evan示范了一个标准的平板支撑姿势，先撑30秒。\n\n小张颤颤巍巍地撑了15秒就趴下了。\n\n没关系，Evan笑着说，明天再来，目标是20秒。后天25秒。下周你就能撑到一分钟了。\n\n这跟写代码有什么关系？小张喘着气问。\n\n关系大了，Evan做了一个完美的俯卧撑站起来，写代码遇到bug的时候，你不能一次就解决。但你每次尝试，都在缩小问题的范围。就像平板支撑，你每次多撑五秒，都在变得更强。关键是不要放弃。\n\n小张想了想，觉得有道理。\n\n一个月后，小张的平板支撑纪录从15秒提升到了两分钟。而他遇到的那几个技术瓶颈，也一个个被攻克了。\n\n他在公司群里发了一条消息：感谢Evan教练。不只是身体变强了，心态也变强了。\n\nEvan回复了一个肌肉表情和一段即兴说唱：从15秒到120秒，你用了一个月的时间，从bug到feature，你用了同样的坚持，身体和代码都是一样的道理，每天进步一点点，最终创造奇迹！\n\n这就是Evan。一个用健身的哲学教人编程、用说唱的节奏写代码、用城中村男孩的真诚改变世界的工程师。\n\n他的故事不是关于天赋或运气，而是关于一种简单的信念：只要你不放弃，世界就不会放弃你。"

extras['周周'] = "\n\n【附录：周周的实验室日记】\n\n周周有一个保持了十五年的习惯，每天写实验室日记。\n\n这个习惯始于大学时期。导师要求实验室的所有成员都保持详细的实验记录，周周把这个要求延续到了日常生活中。她的日记不只是记录实验数据，还记录她的思考、疑惑、发现和感受。\n\n翻看她这十五年的日记，就像在读一部关于AI与儿童发展的编年史：\n\n2018年3月15日：今天第一次设计关于AI对话伙伴对儿童影响的实验。文献综述做了三个月，仍然觉得理论基础不够扎实。这个领域太新了，几乎没有人做过类似的研究。但正因为如此，才更有价值。\n\n2019年6月22日：实验数据出来了！效果比预期还好。但作为一个严谨的研究者，我不能高兴太早。需要做更多的验证，排除其他可能的解释。科学最怕的不是失败，而是过早地宣布成功。\n\n2020年9月8日：今天见了Alex。他的团队很小，产品也很初级，但他的眼睛里有光。那种光是我在学术界很少看到的，一种纯粹的、不掺杂功利目的的热情。也许理论和实践的结合，真的需要这样的人。\n\n2021年4月3日：音频危机期间。我每天都在担心，如果公司撑不过去怎么办？但我更担心的是那些已经在使用AI伙伴的孩子们。如果产品突然停服，他们会怎么想？他们会不会觉得自己的朋友抛弃了他们？这种对儿童的伤害是无法用数据衡量的。我把这个担忧写进了伦理报告，Alex承诺无论发生什么，都会做好善后方案。\n\n2023年12月25日：今天收到了一份特别的新年礼物，小雨的妈妈寄来了一封信和一幅画。画是小雨画的，画的是她、她的朋友小棉（AI伙伴）和她的新朋友小美。三个人手拉手站在一棵大树下。信的结尾写道：谢谢你们让小雨知道了什么是友谊。\n\n我把这幅画贴在了办公桌上。每次看到它，我就会想起为什么选择了这条路，不是为了发表论文或者获得学术荣誉，而是为了那些像小雨一样的孩子。\n\n科学的最终目的不是理解世界，而是让世界变得更好。\n\n周周合上日记本，看着窗外初夏的阳光。实验室里很安静，只有仪器发出轻微的嗡嗡声。\n\n她拿起笔，在今天的日记中写下了最后一行：明天要去三所新学校开始新一轮的调研。又有新的孩子、新的故事、新的数据在等着我。\n\n研究永远不会结束。因为孩子永远在成长。\n\n而我的使命，就是用科学的光，照亮他们成长的路。\n\n她放下笔，微笑着关上了灯。"

extras['KK'] = "\n\n【附录：KK的工作台】\n\n如果你走进KK的办公室，你会看到一个独特的工作台。\n\n工作台的左边是电子工程区。电烙铁、万用表、示波器、各种规格的焊锡丝、一盒盒分类整齐的电子元件。每一件工具都被擦得锃亮，摆放得一丝不苟。KK的父亲送给她的第一把电烙铁（已经退休了）被装在一个玻璃框里，挂在墙上。\n\n工作台的右边是音乐区。一把白色的小提琴（母亲送的），一把黑色的电吉他（自己买的），一个小型音箱，几本乐谱。吉他旁边放着一个拨片盒，里面装着各种颜色和厚度的拨片。\n\n两个区域之间没有任何分隔，而是自然地融合在一起。有时候KK会左手拿着焊锡、右手拿着拨片，在两个世界之间无缝切换。\n\n她的同事们都说，KK的工作台是全公司最有个性的地方。\n\n但KK自己知道，这个工作台不仅仅是一个工作空间。它是她人生的缩影。\n\n左边是父亲教给她的东西，严谨、精确、耐心。每一块电路板的背后，都有她无数个小时的调试和优化。她从父亲那里学到的最重要的一课是：好的工程不是炫技，而是在有限的资源和约束下，找到最优雅的解决方案。\n\n右边是母亲教给她的东西，感受、表达、创造。每一个音符的背后，都有她对世界的感知和回应。她从母亲那里学到的最重要的一课是：技术不是冷冰冰的，它可以承载温度和情感。\n\n当这两股力量交汇在一起，就诞生了斓舟科技的AI伙伴机器人，一个既有精密的硬件设计、又有温暖的交互体验的产品。\n\n每天下班前，KK都会在工作台上停留几分钟。她会检查一遍明天的元器件清单，然后弹几个和弦放松一下。\n\n有时候她会拿起父亲的那把旧电烙铁（玻璃框里的那把），静静地看一会儿。焊头已经发黑了，手柄上的防滑纹路被磨得光滑。这把烙铁伴随了父亲的整个职业生涯，也开启了KK的技术人生。\n\n谢谢您，爸爸。她每次都会轻声说。\n\n然后她会拿起吉他，弹一首母亲最喜欢的那首小星星。不是摇滚版，而是最原始、最简单的那个版本，就像小时候母亲在灯下拉给她听的那样。\n\n琴声在空荡的办公室里回响，温柔而清澈。\n\n这就是KK。一个用焊枪和拨片书写人生的工程师。\n\n她的故事不轰轰烈烈，但每一个焊点、每一个音符，都饱含着对技术的热爱和对人的关怀。\n\n她的终极梦想？不是获得什么大奖或者赚到多少钱。而是有一天，当一个孩子拆开AI伙伴机器人，看到电路板上那个小小的吉他图案，然后说：我也想做这样的东西。\n\n到那个时候，她会微笑着说：欢迎加入。这里的工作台上，永远有放得下两样东西的空间，技术和热爱。\n\n因为在她看来，这两样东西从来就不是分开的。它们只是同一个梦想的两种表达方式。\n\n而那个梦想就是，用双手创造温暖，让世界变得更好一点点。"

for name, extra in extras.items():
    start_pattern = "'" + name + "': `"
    start_idx = content.find(start_pattern)
    if start_idx == -1:
        print(f"WARNING: Could not find {name}")
        continue
    search_from = start_idx + len(start_pattern)
    end_idx = content.find('`', search_from)
    if end_idx == -1:
        print(f"WARNING: Could not find end for {name}")
        continue
    content = content[:end_idx] + extra + content[end_idx:]
    print(f"Extended {name}: +{len(extra)} chars")

with open('/Users/alex/lebotworld-office-game/stories.js', 'w', encoding='utf-8') as f:
    f.write(content)
print("Done!")
